pub const fn sona_p1(_: &Ctx) -> f32 {
    0f32
}

pub const fn sona_p2(ctx: &Ctx) -> f32 {
    (match ctx.level as u8 {
        ..=1 => 20f32,
        2 => 30f32,
        3 => 40f32,
        4 => 50f32,
        5 => 60f32,
        6 => 70f32,
        7 => 80f32,
        8 => 90f32,
        9 => 105f32,
        10 => 120f32,
        11 => 135f32,
        12 => 150f32,
        13 => 165f32,
        14 => 180f32,
        15 => 195f32,
        16 => 210f32,
        17 => 225f32,
        18 => 240f32,
        19 => 255f32,
        20.. => 270f32,
    }) + 0.2 * ctx.ability_power
}

pub const fn sona_p3(ctx: &Ctx) -> f32 {
    0.3 * ctx.ability_power
}

pub const fn sona_p4(ctx: &Ctx) -> f32 {
    0.0004 * ctx.ability_power
}

pub const fn sona_q1(ctx: &Ctx) -> f32 {
    5f32 * (1f32 + 0.02 * ctx.ability_power + ctx.q_level)
}

pub const fn sona_q2(ctx: &Ctx) -> f32 {
    5f32 * (10f32 + 0.08 * ctx.ability_power + 7f32 * (-1f32 + ctx.q_level))
}

pub const fn sona_w1(ctx: &Ctx) -> f32 {
    5f32 * (5f32 + 4f32 * (-1f32 + ctx.w_level))
}

pub const fn sona_r1(ctx: &Ctx) -> f32 {
    150f32 + 100f32 * (-1f32 + ctx.r_level) + ctx.ability_power / 2f32
}

